package org.pacos.plugin.kafka.view.message;
import com.vaadin.flow.component.button.Button; import com.vaadin.flow.component.notification.Notification; import com.vaadin.flow.component.orderedlayout.HorizontalLayout; import com.vaadin.flow.component.orderedlayout.VerticalLayout; import com.vaadin.flow.component.textfield.TextField; import com.vaadin.flow.data.binder.Binder; import org.pacos.plugin.kafka.backend.connection.KafkaConnectionService; import org.pacos.plugin.kafka.backend.message.*; import java.util.*;
public class KafkaMessageView extends VerticalLayout {
 private final KafkaMessageService messages; private final KafkaMessageForm<KafkaMessageDraft> form; private final Binder<KafkaMessageDraft> binder;
 public KafkaMessageView(KafkaConnectionService connections,KafkaMessageService messages){this.messages=messages;form=new KafkaMessageForm<>(connections,messages,KafkaMessageDraft.class);binder=form.create(this,List.of());Button send=new Button("Send",e->send());Button save=new Button("Save configuration",e->save());add(new HorizontalLayout(send,save));}
 private void send(){try{KafkaMessageDraft b=form.write();messages.send(b.getConnectionId(),b.getTopic(),emptyToNull(b.getMessageKey()),b.getPayload());Notification.show("Message sent");}catch(Exception e){Notification.show("Send failed: "+e.getMessage());}}
 private void save(){try{KafkaMessageDraft b=form.write();TextField name=new TextField("Configuration name");com.vaadin.flow.component.dialog.Dialog d=new com.vaadin.flow.component.dialog.Dialog(name);Button ok=new Button("Save",e->{if(name.isEmpty()){name.setInvalid(true);return;}try{messages.saveTemplate(form.toTemplate(name.getValue(),b));d.close();form.refreshTemplates();Notification.show("Configuration saved");}catch(Exception x){Notification.show("Save failed: "+x.getMessage());}});d.add(ok);d.open();}catch(Exception e){Notification.show("Validation failed: "+e.getMessage());}}
 private String emptyToNull(String v){return v==null||v.isBlank()?null:v;}
}